blocks.text:
transaction: {
    enabled: true,
    sideEffects: 'none'
},
cache: {
    enabled: false
},
event: {
    enabled: false
}

databaseTransactions: {
    enabled: true,
    failClosed: true,
    maximumCommitTimeMs: 5000
}

address: {
    super: 'base',
    schemaPolicies: ['customerOwned'],
    model: true
}

backoffice: {
    enabled: true,
    label: 'Address',
    displayProperty: 'code',
    displayProperties: ['city', 'code'],
    operations: ['search', 'read', 'create', 'update', 'delete'],
    relationships: {
        contacts: {
            label: 'Contact methods',
            targetModule: 'profile',
            actions: ['SELECT_EXISTING', 'CREATE_RELATED']
        }
    }
}

backoffice: {
    aggregateOperations: {
        SAVE_WITH_RELATIONSHIPS: {
            enabled: true,
            label: 'Save with related records',
            purpose: 'SAVE_WITH_RELATIONSHIPS',
            consistency: 'ATOMIC',
            service: 'DefaultAddressAggregateService',
            operation: 'saveWithRelationships'
        }
    }
}

refSchema: {
    contacts: {
        enabled: true,
        moduleName: 'profile',
        schemaName: 'contact',
        type: 'many',
        propertyName: 'code',
        onTargetDelete: 'RESTRICT'
    }
}
